CREATE FUNCTION safe_div(a INT, b INT) RETURNS TEXT
LANGUAGE plpgsql AS $$
BEGIN
  RETURN (a / b)::TEXT;
EXCEPTION
  WHEN division_by_zero THEN
    RETURN 'chia 0';
END;
$$;
SELECT safe_div(7, 2) || ' / ' || safe_div(1, 0);

